<?php
declare(strict_types=1); require_once __DIR__.'/../app/bootstrap.php';
if(current_user()) redirect('index.php'); $error='';
if($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); $login=trim((string)($_POST['email']??'')); $password=(string)($_POST['password']??'');
 try { $st=db()->prepare('SELECT id,name,email,password,role,is_active FROM users WHERE email=? LIMIT 1'); $st->execute([$login]); $u=$st->fetch(); if($u && (int)$u['is_active']===1 && password_verify($password,$u['password'])) { session_regenerate_id(true); $_SESSION['gpm_user']=['id'=>(int)$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>$u['role']]; redirect('index.php'); } $error='Credenciais inválidas ou conta inativa.'; } catch(Throwable $e) { $error='Não foi possível ligar à base de dados. Confirme config/database.php.'; }
}
?><!doctype html><html lang="pt"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Entrar | GPM</title><link rel="stylesheet" href="assets/css/admin.css"></head><body class="login-page"><form class="login-card" method="post"><div class="brand-login">GPM<span>.</span></div><h1>Painel administrativo</h1><p class="muted">Entre com a sua conta interna.</p><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><?=csrf_field()?><div class="field"><label for="email">Email</label><input id="email" name="email" type="email" autocomplete="username" required></div><div class="field"><label for="password">Palavra-passe</label><input id="password" name="password" type="password" autocomplete="current-password" required></div><button class="btn" type="submit">Entrar</button><p class="hint">A conta administrativa deve existir na tabela users.</p></form></body></html>
